<?php $rows = ClientApi::data($api->request('GET','api/favorites')); $destinations = ClientApi::data($api->request('GET','api/destinations?page=1&per_page=50')); $destinations = is_array($destinations['items'] ?? null) ? $destinations['items'] : []; $savedIds = array_fill_keys(array_map(static fn($r) => (int)$r['id'], is_array($rows) ? $rows : []), true); ?>
<section class="panel"><h2 class="section-title">Vos destinations enregistrées</h2><?php if (!$rows): ?><div class="empty"><div class="empty-icon">♡</div><h3>Vos favoris vous attendent</h3><p>Choisissez une destination ci-dessous pour commencer votre liste.</p></div><?php else: ?><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(230px,1fr))"><?php foreach ($rows as $r): ?><article class="card"><?php if (!empty($r['image_principale'])): ?><img src="<?= client_h($r['image_principale']) ?>" alt="<?= client_h($r['nom'] ?? 'Destination') ?>" loading="lazy" style="width:100%;height:150px;object-fit:cover;border-radius:12px"><?php endif; ?><h3><?= client_h($r['nom'] ?? '') ?></h3><p class="row-meta"><?= client_h($r['localite'] ?? '') ?> · <?= client_h($r['categorie'] ?? '') ?></p><p><?= client_h(mb_strimwidth((string)($r['description'] ?? ''),0,145,'…')) ?></p><form method="post"><?= client_csrf_field() ?><input type="hidden" name="action" value="favorite_remove"><input type="hidden" name="id" value="<?= (int)$r['favori_id'] ?>"><button class="btn btn-outline" type="submit">Retirer des favoris</button></form></article><?php endforeach; ?></div><?php endif; ?></section>
<section class="panel" style="margin-top:18px"><h2 class="section-title">Découvrir d’autres destinations</h2><?php if (!$destinations): ?><p class="row-meta">Aucune destination publiée n’est disponible actuellement.</p><?php else: ?><div class="list"><?php foreach ($destinations as $d): ?><div class="list-row"><div><div class="row-title"><?= client_h($d['nom'] ?? '') ?></div><div class="row-meta"><?= client_h($d['localite'] ?? '') ?> · <?= client_h($d['categorie'] ?? '') ?></div></div><?php if (isset($savedIds[(int)$d['id']])): ?><span class="badge good">Dans vos favoris</span><?php else: ?><form method="post"><?= client_csrf_field() ?><input type="hidden" name="action" value="favorite_add"><input type="hidden" name="destination_id" value="<?= (int)$d['id'] ?>"><button class="btn btn-outline" type="submit">Ajouter</button></form><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?></section>
